package it.financemanager.architecture;
import org.junit.jupiter.api.Test;import java.io.*;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class HexagonalArchitectureTest{@Test void domainAndApplicationAreFrameworkIndependent()throws IOException{List<String> violations=new ArrayList<>();try(var files=Files.walk(Path.of("src/main/java/it/financemanager"))){files.filter(p->p.toString().endsWith(".java")).filter(p->p.toString().contains("/domain/")||p.toString().contains("/application/")).forEach(p->{try{String s=Files.readString(p);if(s.contains("org.springframework")||s.contains("jakarta.persistence")||s.contains("it.financemanager.infrastructure"))violations.add(p.toString());}catch(IOException e){throw new UncheckedIOException(e);}});}assertThat(violations).isEmpty();}}
